    if (-not [IO.Directory]::Exists($FrappeDockerRoot)) { throw 'APEX_FRAPPE_DOCKER_ROOT_NOT_FOUND' }; if (-not [IO.File]::Exists($ComposeFile)) { throw 'APEX_PHASE4_COMPOSE_FILE_NOT_FOUND' }; if (-not [IO.File]::Exists($LoopbackOverride)) { throw 'APEX_PHASE4_LOOPBACK_OVERRIDE_NOT_FOUND' }
