    $pred=@(Get-ChildItem -LiteralPath $EvidenceBase -File -Filter 'watany-control-center-erpnext-phase3-backend-only-*.zip.final-reopen-validation.json' | Sort-Object LastWriteTime -Descending); if($pred.Count -lt 1){throw 'APEX_PHASE4_PREDECESSOR_SIDECAR_NOT_FOUND'}; $side=([IO.File]::ReadAllText($pred[0].FullName)|ConvertFrom-Json); $zip=[string]$side.validationTarget; if(([string]$side.status -ne 'PASS') -or ([string]$side.finalZipReopenValidation -ne 'PASS') -or ([string]$side.preWorkerGate -ne 'PASS') -or ([string]$side.workerStartAuthorization -ne 'READY_FOR_SEPARATE_AUTHORITY') -or ([string]$side.productionMutation -ne 'NO') -or (-not [IO.File]::Exists($zip))){throw 'APEX_PHASE4_PREDECESSOR_VALIDATION_BLOCKED'}; $predProof=[ordered]@{status='PASS';sidecar=$pred[0].FullName;sidecarSha256=(Get-FileSha256 $pred[0].FullName);zip=$zip;zipSha256=(Get-FileSha256 $zip);entryCount=$side.entryCount;finalZipReopenValidation=$side.finalZipReopenValidation;preWorkerGate=$side.preWorkerGate;workerStartAuthorization=$side.workerStartAuthorization;productionMutation=$side.productionMutation}; Write-Json '03_PHASE3_PREDECESSOR_VALIDATION.json' $predProof; Gate 'PHASE4_PREDECESSOR_VALIDATION' 'PASS' $zip
